 static std::shared_ptr<BitmapAlphabet> get(bool dark=false){static std::array<std::weak_ptr<BitmapAlphabet>,2> cache;auto& weak=cache[dark?1:0];static std::mutex mutex;std::lock_guard<std::mutex> lock(mutex);auto atlas=weak.lock();if(!atlas){atlas=std::make_shared<BitmapAlphabet>(dark);weak=atlas;}return atlas;}
