class SnapSlider : public Slider {
 bool shiftHeld=false;
public:
 double snapValue(double attempted,DragMode mode)override{if(shiftHeld&&mode!=notDragging){double lo=std::ceil(getMinimum()),hi=std::floor(getMaximum());if(lo<=hi)return jlimit(lo,hi,std::round(attempted));}return Slider::snapValue(attempted,mode);}
 void mouseDown(const MouseEvent& e)override{shiftHeld=e.mods.isShiftDown();Slider::mouseDown(e);}
 void mouseDrag(const MouseEvent& e)override{shiftHeld=e.mods.isShiftDown();Slider::mouseDrag(e);}
 void mouseUp(const MouseEvent& e)override{Slider::mouseUp(e);shiftHeld=false;}
 void mouseWheelMove(const MouseEvent& e,const MouseWheelDetails& w)override{shiftHeld=e.mods.isShiftDown();Slider::mouseWheelMove(e,w);shiftHeld=false;}
};
