 struct ModeButton{std::unique_ptr<DrawnModeButton> button;int parameter,index;};std::vector<ModeButton> modes;
 void setValue(int id,float value){auto* a=p.state.getParameter(knc::ids[id]);a->beginChangeGesture();a->setValueNotifyingHost(a->convertTo0to1(value));a->endChangeGesture();}
 void setSync(float x){setValue(knc::DSync,x);refresh();}
 void refresh(){look.setTheme(p.darkMode.load());auto values=p.values();for(auto& mode:modes)mode.button->setToggleState(roundToInt(values[mode.parameter])==mode.index,dontSendNotification);if(delay){bool mono=values[knc::DMode]<.5f;for(auto& slider:sliders)if(slider->getName()=="delaySpread"){slider->setEnabled(!mono);if(mono&&slider->getValue()!=0)setValue(knc::DSpread,0);}bool sync=values[knc::DSync]>.5f;ms.setToggleState(!sync,dontSendNotification);beat.setToggleState(sync,dontSendNotification);division.setVisible(sync);if(!sliders.empty())sliders.front()->setVisible(!sync);}repaint();}
 void timerCallback()override{refresh();}
 void addModes(int parameter,std::initializer_list<const char*> names,int x,int y,int width,int height){int i=0,count=int(names.size()),cell=width/count;for(auto text:names){auto button=std::make_unique<DrawnModeButton>(text);button->setName(String(knc::ids[parameter])+String(i));if(parameter==knc::DMode)button->setBounds(x,y+i*17,width,17);else button->setBounds(x+i*cell,y,cell-2,height);button->onClick=[this,parameter,i]{setValue(parameter,float(i));if(parameter==knc::DMode&&i==0)setValue(knc::DSpread,0);refresh();};addAndMakeVisible(*button);modes.push_back({std::move(button),parameter,i++});}}
