 void updateHover(const MouseEvent& e){float y=e.position.y*78/getHeight();hoverDb=y<24?jlimit(0.f,1.f,(24-y)/14):jlimit(-60.f,0.f,(24-y)*60/31);if(hover)hover(true);}
