 void file(bool writing){KNCProcessor::userPresetDirectory().createDirectory();chooser=std::make_unique<FileChooser>(writing?"Save preset":"Load preset",KNCProcessor::userPresetDirectory(),"*.kncoff");Component::SafePointer<KNCEditor> safe(this);chooser->launchAsync(writing?(FileBrowserComponent::saveMode|FileBrowserComponent::canSelectFiles|FileBrowserComponent::warnAboutOverwriting):(FileBrowserComponent::openMode|FileBrowserComponent::canSelectFiles),[safe,writing](const FileChooser& c){if(!safe)return;auto f=c.getResult();if(f==File{})return;MemoryBlock b;if(writing){if(!safe->p.saveUserPreset(f.getFileNameWithoutExtension()))AlertWindow::showMessageBoxAsync(AlertWindow::WarningIcon,"Preset","Could not save preset.");}else if(!safe->p.loadUserPreset(f))AlertWindow::showMessageBoxAsync(AlertWindow::WarningIcon,"Preset","Could not load preset.");safe->repaint();});}
